rss.channel:
	ionas Wissen

	https://www.ionas.com/wissen/
	Artikel, Videos, Anleitungen, Tipps ...
	de-DE
{{- $beitraege := (where (where site.RegularPages "Section" "wissen") "Params.suche" "!=" true).ByDate.Reverse }}
{{- with (first 1 $beitraege) }}{{ range . }}
	{{ .Lastmod.UTC.Format "Mon, 02 Jan 2006 15:04:05 +0000" }}
{{- end }}{{ end }}
{{- range first 10 $beitraege }}


		{{ .Title }}
		{{ .Permalink }}
		{{ .Params.autor }}
		{{ .Date.UTC.Format "Mon, 02 Jan 2006 15:04:05 +0000" }}
		https://www.ionas.com/wissen/?p={{ .Params.wp_id }}
		{{ .Params.beschreibung }}
		{{ .Content }}

{{- end }}
